def forward(groups):
    date_part = groups[0]
    space = groups[1]
    time_part = groups[2]
    dt = datetime.strptime(date_part + time_part, '%y%m%d%H%M%S')
    return {'stored': [int(dt.timestamp() * 1000)], 'layout': [len(space)]}

def inverse(record):
    millis = int(record['stored'][0])
    space_length = record['layout'][0]
    dt = datetime.fromtimestamp(millis / 1000)
    space = ' ' * space_length
    return dt.strftime('%y%m%d') + space + dt.strftime('%H%M%S')
